const EPS=1e-6;
export const cross=(a,b)=>a.x*b.y-a.y*b.x;
export const sub=(a,b)=>({x:a.x-b.x,y:a.y-b.y});
export const mix=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function polygon(o){let p=o.type==='triangle'?[[0,o.h],[o.w/2,0],[o.w,o.h]]:o.type==='trapezoid'?[[o.w*.2,0],[o.w*.8,0],[o.w,o.h],[0,o.h]]:o.type==='parallelogram'?[[o.w*.25,0],[o.w,0],[o.w*.75,o.h],[0,o.h]]:o.type==='l'?[[0,0],[o.w,0],[o.w,o.h-o.cutH],[o.w-o.cutW,o.h-o.cutH],[o.w-o.cutW,o.h],[0,o.h]]:[[0,0],[o.w,0],[o.w,o.h],[0,o.h]];const r=(o.rotation||0)*Math.PI/180,c=Math.cos(r),s=Math.sin(r);return p.map(([x,y])=>({x:o.x+o.w/2+(x-o.w/2)*c-(y-o.h/2)*s,y:o.y+o.h/2+(x-o.w/2)*s+(y-o.h/2)*c}));}
export const edges=p=>p.map((a,i)=>({a,b:p[(i+1)%p.length]}));
export function parameter(p,a,b){const d=sub(b,a),l=d.x*d.x+d.y*d.y;return l?((p.x-a.x)*d.x+(p.y-a.y)*d.y)/l:0;}
export function on(p,a,b){return Math.abs(cross(sub(p,a),sub(b,a)))<EPS*Math.max(1,distance(a,b))&&parameter(p,a,b)>=-EPS&&parameter(p,a,b)<=1+EPS;}
export function cuts(a,b,c,d){const r=sub(b,a),s=sub(d,c),den=cross(r,s);if(Math.abs(den)<EPS)return [c,d].filter(p=>on(p,a,b)).map(p=>parameter(p,a,b));const t=cross(sub(c,a),s)/den,u=cross(sub(c,a),r)/den;return t>=-EPS&&t<=1+EPS&&u>=-EPS&&u<=1+EPS?[Math.max(0,Math.min(1,t))]:[];}
export function inside(p,poly){if(edges(poly).some(e=>on(p,e.a,e.b)))return true;let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)yes=!yes;}return yes;}
export function contained(shape,foundations){const polys=foundations.map(polygon),p=polygon(shape),all=polys.flatMap(edges),covered=q=>polys.some(f=>inside(q,f));return p.every(covered)&&edges(p).every(e=>{const ts=[0,1,...all.flatMap(f=>cuts(e.a,e.b,f.a,f.b))].sort((a,b)=>a-b);return ts.slice(1).every((t,i)=>covered(mix(e.a,e.b,(ts[i]+t)/2)));})&&unionArea([...foundations,shape])-unionArea(foundations)<1e-5;}
const keypoint=p=>`${p.x.toFixed(5)},${p.y.toFixed(5)}`;
export function segments(shapes,previous=[]){const all=shapes.flatMap(o=>edges(polygon(o)).map((e,index)=>({...e,owner:o.id,index,layer:o.layer}))),map=new Map();for(const e of all){const ts=[0,1,...all.flatMap(f=>cuts(e.a,e.b,f.a,f.b))].sort((a,b)=>a-b).filter((t,i,a)=>!i||t-a[i-1]>EPS);for(let i=1;i<ts.length;i++){const a=mix(e.a,e.b,ts[i-1]),b=mix(e.a,e.b,ts[i]);if(distance(a,b)<EPS)continue;const key=[keypoint(a),keypoint(b)].sort().join('|');const ref={owner:e.owner,index:e.index,start:ts[i-1],end:ts[i]},mid=(ts[i]+ts[i-1])/2;const old=previous.find(w=>w.enabled&&((w.refs||[]).some(r=>r.owner===e.owner&&r.index===e.index&&mid>=r.start-EPS&&mid<=r.end+EPS)||on(mix(a,b,.5),w.a,w.b)&&Math.abs(cross(sub(b,a),sub(w.b,w.a)))<EPS));if(map.has(key)){const w=map.get(key);w.owners.push(e.owner);w.refs.push(ref);w.enabled ||= !!old;continue}map.set(key,{key,a,b,owners:[e.owner],refs:[ref],enabled:!!old});}}return [...map.values()];}
export function area(p){return Math.abs(p.reduce((a,v,i)=>a+cross(v,p[(i+1)%p.length]),0))/2;}
export function unionArea(shapes){const polys=shapes.map(polygon),all=polys.flatMap(edges),xs=polys.flat().map(p=>p.x);for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++)for(const t of cuts(all[i].a,all[i].b,all[j].a,all[j].b))xs.push(mix(all[i].a,all[i].b,t).x);xs.sort((a,b)=>a-b);let total=0;for(let i=1;i<xs.length;i++){const w=xs[i]-xs[i-1];if(w<EPS)continue;const x=(xs[i]+xs[i-1])/2,intervals=[];for(const p of polys){const ys=edges(p).filter(e=>(e.a.x>x)!==(e.b.x>x)).map(e=>e.a.y+(x-e.a.x)*(e.b.y-e.a.y)/(e.b.x-e.a.x)).sort((a,b)=>a-b);for(let j=0;j+1<ys.length;j+=2)intervals.push([ys[j],ys[j+1]]);}intervals.sort((a,b)=>a[0]-b[0]);let lo=null,hi=0,len=0;for(const [a,b]of intervals){if(lo===null){lo=a;hi=b}else if(a<=hi)hi=Math.max(hi,b);else{len+=hi-lo;lo=a;hi=b}}if(lo!==null)len+=hi-lo;total+=len*w;}return total;}
